svg.script:
var S = { on:false, state:'OFF', phase:'idle', phaseT:0, ldr:0.8,
          blinkT:0, blinkClosed:false, happyT:0, waitWake:0, log:[] };
var $ = function(id){ return document.getElementById(id); };
function now(){ return new Date().getTime(); }

function logLine(s){
  S.log.push("[" + new Date().toLocaleTimeString('zh-CN',{hour12:false}) + "] " + s);
  if (S.log.length > 7) S.log.shift();
  var g = $("log"); while (g.firstChild) g.removeChild(g.firstChild);
  for (var i=0;i<S.log.length;i++){
    var t = document.createElementNS("http://www.w3.org/2000/svg","text");
    t.setAttribute("x",80); t.setAttribute("y",428+i*20); t.textContent = S.log[i];
    g.appendChild(t);
  }
}
function show(id,v){ $(id).setAttribute('visibility', v?'visible':'hidden'); }
function wire(id,on){ $(id).classList[on?'add':'remove']('on'); }
function setState(s,label){ S.state=s; $("st-label").textContent=s; $("st-label").setAttribute('fill',
  s==='SLEEP'?'#64748b':s==='HAPPY'?'#f472b6':s==='LISTEN'?'#a78bfa':s==='SPEAK'?'#7c3aed':'#22d3ee');
  if(label) $("st-sub").textContent=label; }

function togglePower(){
  S.on = !S.on;
  if (S.on){
    setState('BOOT','开机表演：欢叫+摆头'); S.phase='boot'; S.phaseT=now();
    logLine("[Robot] booting..."); logLine("[Audio] I2S mic+spk ready");
    wire('w-scl',true); wire('w-sda',true);
    show('eyes-open',true);
  } else {
    setState('OFF','已关机'); S.phase='idle';
    ['w-scl','w-sda','w-sck','w-ws','w-sd','w-pan','w-tilt','w-touch','w-ldr','w-bclk','w-lrc','w-din'].forEach(function(w){wire(w,false);});
    ['eyes-open','eyes-happy','eyes-closed','eyes-surprise'].forEach(function(e){show(e,false);});
    logLine("[Robot] power off");
  }
  document.getElementById('mcu').querySelector('rect').classList[S.on?'add':'remove']('powered');
}
function petPet(){
  if (!S.on) return logLine("[!] 请先开机");
  logLine("[Robot] pet!");
  setState('HAPPY','开心！点头+触发语音'); S.happyT = now();
  wire('w-pan',true); wire('w-tilt',true);
  document.getElementById('servopanhead').classList.add('on');
  show('eyes-open',false); show('eyes-happy',true); show('eyes-surprise',false);
  startVoice();
}
function talk(){
  if (!S.on) return logLine("[!] 请先开机");
  if (S.phase!=='idle') return logLine("[voice] busy, skipped");
  logLine("[Robot] pet!");
  startVoice();
}
function startVoice(){
  S.phase='cuein'; S.phaseT=now(); wire('w-din',true); wire('w-bclk',true); wire('w-lrc',true);
  logLine("[voice] cue 滴 (1047Hz) → record");
  $("st-phase").textContent = "voice: cue-in 滴~";
}
function endVoice(){
  S.phase='idle';
  ['w-sck','w-ws','w-sd','w-din','w-bclk','w-lrc'].forEach(function(w){wire(w,false);});
  $('micwave').classList.remove('on');
  ['eq1','eq2','eq3','eq4'].forEach(function(e){$(e).classList.remove('on');});
  $("st-phase").textContent = "voice: idle";
  logLine("[voice] done → idle");
}

// 光照拖动
var dragging = false;
$('hit-light').addEventListener('mousedown',function(e){dragging=true;moveLight(e);});
window.addEventListener('mousemove',function(e){if(dragging)moveLight(e);});
window.addEventListener('mouseup',function(){dragging=false;});
function moveLight(e){
  var x = (e.clientX !== undefined) ? e.clientX : 0;
  var rect = document.querySelector('svg').getBoundingClientRect();
  var rel = (x - rect.left - 640*(rect.width/1400)) / (300*(rect.width/1400));
  S.ldr = Math.max(0, Math.min(1, rel));
  $('lightfill').setAttribute('width', 300*S.ldr);
  $('lightknob').setAttribute('cx', 640+300*S.ldr);
  $('st-ldrbar').setAttribute('width', 340*S.ldr);
  $('st-ldrbar').setAttribute('fill', S.ldr<0.2?'#dc2626':'#059669');
  $('st-ldrtext').textContent = "光照: " + Math.round(S.ldr*100) + "% (" + (S.ldr<0.2?"天黑→睡觉":"天亮") + ")";
}

setInterval(function(){
  var t = now(), dt = t - S.phaseT;
  if (!S.on) return;

  // 待机眨眼
  if (S.phase==='idle' && S.state==='IDLE'){
    if (t - S.blinkT > 3200){
      S.blinkT = t; S.blinkClosed = !S.blinkClosed;
      show('eyes-open', !S.blinkClosed);
    }
  }
  // BOOT → IDLE
  if (S.phase==='boot' && dt>2000){
    S.phase='idle'; setState('IDLE','待机：眨眼环视 · 显示时间');
    logLine("[Robot] ready. → Idle");
    S.blinkT = t;
  }
  // 语音流程
  if (S.phase==='cuein' && dt>250){
    S.phase='rec'; S.phaseT=t; setState('LISTEN','录音中 3 秒（瞪大眼）');
    show('eyes-open',false); show('eyes-surprise',true);
    ['w-sck','w-ws','w-sd'].forEach(function(w){wire(w,true);});
    $('micwave').classList.add('on');
    logLine("[voice] recording 3000ms...");
  }
  if (S.phase==='rec'){
    $("st-phase").textContent = "voice: recording " + Math.max(0,(3000-dt)/1000).toFixed(1) + "s";
    if (dt>3000){
      S.phase='cueout'; S.phaseT=t;
      show('eyes-surprise',false); show('eyes-open',true);
      ['w-sck','w-ws','w-sd'].forEach(function(w){wire(w,false);});
      $('micwave').classList.remove('on');
      logLine("[voice] cue 嘟 (1319Hz) → playback");
    }
  }
  if (S.phase==='cueout' && dt>250){
    S.phase='play'; S.phaseT=t; setState('SPEAK','回放你的声音');
    ['w-din','w-bclk','w-lrc'].forEach(function(w){wire(w,true);});
    ['eq1','eq2','eq3','eq4'].forEach(function(e){$(e).classList.add('on');});
  }
  if (S.phase==='play'){
    $("st-phase").textContent = "voice: playing back...";
    if (dt>3000){
      // 回到开心尾巴或待机
      if (t - S.happyT < 6000) { setState('HAPPY','开心中…'); S.phase='idle'; }
      else endVoice();
      if (S.phase==='idle'){ setState('IDLE','待机：眨眼环视 · 显示时间'); show('eyes-happy',false); show('eyes-open',true);
        ['w-din','w-bclk','w-lrc'].forEach(function(w){wire(w,false);});
        ['eq1','eq2','eq3','eq4'].forEach(function(e){$(e).classList.remove('on');});
        $("st-phase").textContent="voice: idle";
      }
      wire('w-pan',false); wire('w-tilt',false);
      document.getElementById('servopanhead').classList.remove('on');
    }
  }
  // HAPPY 超时
  if (S.state==='HAPPY' && S.phase==='idle' && t-S.happyT>3000 && t-S.happyT<29000){
    setState('IDLE','待机：眨眼环视 · 显示时间');
    show('eyes-happy',false); show('eyes-open',true);
    wire('w-pan',false); wire('w-tilt',false);
    document.getElementById('servopanhead').classList.remove('on');
  }
  // 光照 → 睡 / 醒
  if (S.ldr < 0.2 && S.state!=='SLEEP' && S.phase==='idle'){
    setState('SLEEP','天黑了…自动入睡 (60s阈值·仿真加速)');
    show('eyes-open',false); show('eyes-happy',false); show('eyes-closed',true);
    logLine("[Robot] too dark → Sleep");
    S.waitWake = 0;
  }
  if (S.ldr >= 0.2 && S.state==='SLEEP'){
    S.waitWake = S.waitWake || t;
    if (t - S.waitWake > 1500){
      setState('IDLE','亮了！自动醒来'); S.waitWake = 0;
      show('eyes-closed',false); show('eyes-open',true);
      logLine("[Robot] light back → Idle");
    }
  } else if (S.ldr < 0.2) S.waitWake = 0;
}, 100);
